%% EE3005 Image Processing - Assignment 2
% Burak Bekir Cakirer (2211011008)
% Prerequisite: MATLAB with Image Processing Toolbox.
% Input noise realizations are fixed PNGs generated by Python_Reference,
% so that all figures use the same corruption across implementations.
% Run this file from any working directory. Generated MATLAB-only previews
% and tables are saved to Outputs/MATLAB_Figures and Outputs/MATLAB_Results.
clear; close all; clc;
root = fileparts(fileparts(mfilename('fullpath')));
src = fullfile(root, 'Source_Images', 'Prepared_Inputs');
out = fullfile(root, 'Outputs', 'MATLAB_Figures');
res = fullfile(root, 'Outputs', 'MATLAB_Results');
if ~exist(out,'dir'), mkdir(out); end
if ~exist(res,'dir'), mkdir(res); end
need = {'brain_mri_gray.png','chest_xray_gray.png','gaussian_noise.png', ...
    'sp_noise.png','salt_only.png','pepper_only.png','pipeline_mixed_input.png'};
for i=1:numel(need)
    assert(exist(fullfile(src,need{i}),'file')==2, ['Missing input: ' need{i}]);
end
brain = im2double(imread(fullfile(src,'brain_mri_gray.png')));
chest = im2double(imread(fullfile(src,'chest_xray_gray.png')));
ng = im2double(imread(fullfile(src,'gaussian_noise.png')));
ns = im2double(imread(fullfile(src,'sp_noise.png')));
salt = im2double(imread(fullfile(src,'salt_only.png')));
pepper = im2double(imread(fullfile(src,'pepper_only.png')));

%% Task 1: Histogram equalization, AHE, and CLAHE
imHE = histeq(chest,256);
imAHE = adapthisteq(chest,'NumTiles',[8 8],'ClipLimit',1,'NBins',256);
imCL1 = adapthisteq(chest,'NumTiles',[8 8],'ClipLimit',0.01,'NBins',256);
imCL2 = adapthisteq(chest,'NumTiles',[16 16],'ClipLimit',0.03,'NBins',256);
labels={'Original','Global HE','AHE 8x8','CLAHE 8x8 L=0.01','CLAHE 16x16 L=0.03'};
imgs={chest,imHE,imAHE,imCL1,imCL2};
f=figure('Visible','off','Position',[50 50 1650 640]);
for i=1:5
    subplot(2,5,i); imshow(imgs{i},[]); title(labels{i});
    subplot(2,5,i+5); histogram(imgs{i}(:),64,'BinLimits',[0 1]);
    xlim([0,1]); xlabel('Normalized gray level');
end
save_figure(f,out,'M01_contrast_histograms.png');

%% Task 2: Manual kernel and boundary rules
A=[10 20 30 40 50;15 25 35 45 55;20 30 40 50 60; ...
   25 35 45 55 65;30 40 50 60 70];
K=[1 0 -1;2 0 -2;1 0 -1];
patch=A(2:4,2:4); corrTerms=patch.*K;
convTerms=patch.*rot90(K,2);
corrValue=sum(corrTerms(:)); convValue=sum(convTerms(:));
assert(corrValue==-80 && convValue==80);
fid=fopen(fullfile(res,'task02_manual_calculations.txt'),'w');
fprintf(fid,'A center patch:\n%s\nKernel:\n%s\n',mat2str(patch),mat2str(K));
fprintf(fid,'Correlation products:\n%s\nSum: %d\n',mat2str(corrTerms),corrValue);
fprintf(fid,'Convolution products:\n%s\nSum: %d\n',mat2str(convTerms),convValue);
fclose(fid);
roi=chest(141:650,166:620);
meanK=ones(3,3)/9;
pp={imfilter(roi,meanK,0,'same','corr'), ...
    imfilter(roi,meanK,'replicate','same','corr'), ...
    mirror_mean_3x3(roi), ...
    imfilter(roi,meanK,'circular','same','corr')};
names={'Zero','Replicate','Mirror (no edge repeat)','Circular'};
f=figure('Visible','off','Position',[50 50 1320 720]);
for i=1:4
    subplot(2,4,i); imshow(pp{i},[]); title(names{i});
    subplot(2,4,i+4); imshow(pp{i}(1:70,1:90),[0 1]); title([names{i} ' boundary crop']);
end
save_figure(f,out,'M02_padding.png');

%% Task 3: 3x3 Gaussian from outer product
h=[1;2;1]/4; v=[1 2 1]/4;
G=h*v; expected=[1 2 1;2 4 2;1 2 1]/16;
assert(isequal(G,expected));
direct=imfilter(brain,G,'symmetric','same','corr');
separable=imfilter(imfilter(brain,v,'symmetric','same','corr'),h,'symmetric','same','corr');
maxDiff=max(abs(direct(:)-separable(:)));
f=figure('Visible','off','Position',[50 50 1400 450]);
for i=1:4
    subplot(1,4,i);
    switch i
        case 1, imshow(brain,[]); title('Original');
        case 2, imshow(direct,[]); title('Direct 3x3');
        case 3, imshow(separable,[]); title('Separable 1D');
        case 4, imshow(abs(direct-separable)*1e12,[0 1]); title('Difference x 1e12');
    end
end
save_figure(f,out,'M03_separable.png');
fprintf('Task 2 corr = %g, conv = %g\n',corrValue,convValue);
fprintf('Task 3 maximum absolute difference = %.16g\n',maxDiff);

%% Task 4: Linear filters, both noise types
mk3=fspecial('average',[3 3]); mk5=fspecial('average',[5 5]);
gk3=fspecial('gaussian',[3 3],0.8); gk7=fspecial('gaussian',[7 7],1.4);
noiseNames={'Gaussian sigma=0.06','Salt-pepper density=0.08'};
noiseImgs={ng,ns};
filterNames={'Noisy','Mean 3x3','Mean 5x5','Gaussian 3x3 sigma=0.8','Gaussian 7x7 sigma=1.4'};
t4_noise={};t4_filter={};t4_psnr=[];
for ni=1:2
    current=noiseImgs{ni};
    filtered={current,imfilter(current,mk3,'symmetric','same'), ...
       imfilter(current,mk5,'symmetric','same'), ...
       imfilter(current,gk3,'symmetric','same'), ...
       imfilter(current,gk7,'symmetric','same')};
    f=figure('Visible','off','Position',[50 50 1250 810]);
    subplot(2,3,1);imshow(brain,[]);title('Clean reference');
    for j=1:5
        curPSNR=calc_psnr(brain,filtered{j});
        t4_noise{end+1,1}=noiseNames{ni}; %#ok<SAGROW>
        t4_filter{end+1,1}=filterNames{j}; %#ok<SAGROW>
        t4_psnr(end+1,1)=curPSNR; %#ok<SAGROW>
        subplot(2,3,j+1); imshow(filtered{j},[]);
        title(sprintf('%s | %.2f dB',filterNames{j},curPSNR));
    end
    save_figure(f,out,sprintf('M04_noise_%d.png',ni));
end
writetable(table(t4_noise,t4_filter,t4_psnr,'VariableNames', ...
    {'NoiseType','Filter','PSNR_dB'}),fullfile(res,'task04_psnr_matlab.csv'));

%% Task 5: Median, geometric, harmonic, contra-harmonic
med3=medfilt2(ns,[3 3],'symmetric');
med5=medfilt2(ns,[5 5],'symmetric');
mean3=imfilter(ns,mk3,'symmetric','same');
geo3=exp(imfilter(log(max(ng,1/255)),mk3,'symmetric','same'));
harm3=1./imfilter(1./max(ng,1/255),mk3,'symmetric','same');
cSp=contra_mean(salt,3,-1.5);
cSm=contra_mean(salt,3,+1.5);
cPp=contra_mean(pepper,3,+1.5);
cPm=contra_mean(pepper,3,-1.5);
f=figure('Visible','off','Position',[50 50 1290 800]);
show_grid({brain,ns,mean3,med3,med5}, ...
  {'Clean','Impulse noisy','Mean 3x3','Median 3x3','Median 5x5'},2,3);
save_figure(f,out,'M05_median.png');
f=figure('Visible','off','Position',[50 50 1290 800]);
show_grid({brain,ng,geo3,harm3,imfilter(ng,mk3,'symmetric','same')}, ...
  {'Clean','Gaussian noisy','Geometric mean','Harmonic mean','Arithmetic mean'},2,3);
save_figure(f,out,'M06_mean_variants.png');
f=figure('Visible','off','Position',[50 50 1550 800]);
show_grid({brain,salt,pepper,cSm,cSp,cPp,cPm}, ...
  {'Clean','Salt only','Pepper only','Salt +Q','Salt -Q','Pepper +Q','Pepper -Q'},2,4);
save_figure(f,out,'M07_contraharmonic.png');
t5_N={'mixed';'mixed';'mixed';'Gaussian';'Gaussian';'salt';'salt';'pepper';'pepper'};
t5_F={'Mean3';'Median3';'Median5';'Geometric3';'Harmonic3';'Contra+1.5';'Contra-1.5';'Contra+1.5';'Contra-1.5'};
t5_X={mean3,med3,med5,geo3,harm3,cSm,cSp,cPp,cPm};
psnr_values=zeros(numel(t5_X),1);
for i=1:numel(t5_X), psnr_values(i)=calc_psnr(brain,t5_X{i});end
writetable(table(t5_N,t5_F,psnr_values,'VariableNames', ...
 {'NoiseType','Filter','PSNR_dB'}),fullfile(res,'task05_psnr_matlab.csv'));

%% Task 6: Unsharp mask
blur=imfilter(brain,fspecial('gaussian',[5 5],1.2),'symmetric','same');
gains=[0.5,1,2.5]; sharp=cell(1,3);
for j=1:3
    sharp{j}=min(max(brain+gains(j)*(brain-blur),0),1);
end
f=figure('Visible','off','Position',[50 50 1250 800]);
show_grid({brain,blur,sharp{1},sharp{2},sharp{3}}, ...
 {'Original','Blurred','Gain 0.5','Gain 1.0','Gain 2.5'},2,3);
save_figure(f,out,'M08_unsharp.png');

%% Task 7: First/second derivative, LoG and DoG
sx=fspecial('sobel');sy=sx';
sob=@(x)hypot(imfilter(x,sx,'symmetric','same','corr'), ...
    imfilter(x,sy,'symmetric','same','corr'))/8;
lk=[0 1 0;1 -4 1;0 1 0];
lap=@(x)imfilter(x,lk,'symmetric','same','corr');
logResp=lap(imfilter(brain,fspecial('gaussian',[7 7],1.2),'symmetric','same'));
dog12=imfilter(brain,fspecial('gaussian',[9 9],1),'symmetric','same')- ...
    imfilter(brain,fspecial('gaussian',[17 17],2),'symmetric','same');
dog24=imfilter(brain,fspecial('gaussian',[17 17],2),'symmetric','same')- ...
    imfilter(brain,fspecial('gaussian',[33 33],4),'symmetric','same');
f=figure('Visible','off','Position',[50 50 1540 760]);
show_grid({brain,abs(sob(brain)),abs(lap(brain)),abs(logResp),abs(dog12),abs(dog24), ...
 abs(sob(ng)),abs(lap(ng))}, ...
 {'Original','Sobel','Laplacian','LoG','DoG 1,2','DoG 2,4', ...
 'Sobel Gaussian noisy','Laplacian Gaussian noisy'},2,4);
save_figure(f,out,'M09_edges.png');

%% Task 8: Denoise -> CLAHE -> moderate sharpening
mix=im2double(imread(fullfile(src,'pipeline_mixed_input.png')));
stage1=medfilt2(mix,[3 3],'symmetric');
stage2=adapthisteq(stage1,'NumTiles',[8 8],'ClipLimit',0.01,'NBins',256);
stageBlur=imfilter(stage2,fspecial('gaussian',[5 5],1.1),'symmetric','same');
stage3=min(max(stage2+0.7*(stage2-stageBlur),0),1);
f=figure('Visible','off','Position',[50 50 1350 800]);
show_grid({chest,mix,stage1,stage2,stage3}, ...
 {'Clean reference','Mixed noisy input','Median denoising','CLAHE','Unsharp output'},2,3);
save_figure(f,out,'M10_pipeline.png');
labels={'Noisy';'Denoised';'CLAHE';'Sharpened'};
psnrout=[calc_psnr(chest,mix);calc_psnr(chest,stage1); ...
    calc_psnr(chest,stage2);calc_psnr(chest,stage3)];
writetable(table(labels,psnrout,'VariableNames',{'Stage','PSNR_dB'}), ...
    fullfile(res,'task08_psnr_matlab.csv'));
fprintf('MATLAB outputs generated successfully in %s\n',out);

%% Local utility routines
function val=calc_psnr(ref,out)
    mse=mean((double(ref(:))-double(out(:))).^2);
    if mse==0, val=Inf; else, val=10*log10(1/mse); end
end
function out=contra_mean(x,n,q)
    w=ones(n,n)/(n*n);
    if q<0, z=max(double(x),1/255); else, z=double(x); end
    a=imfilter(z.^(q+1),w,'symmetric','same');
    b=imfilter(z.^q,w,'symmetric','same');
    out=zeros(size(z)); idx=b>1e-12; out(idx)=a(idx)./b(idx);
    out=min(max(out,0),1);
end
function save_figure(fig,out,name)
    set(fig,'Color','w');
    exportgraphics(fig,fullfile(out,name),'Resolution',180);
    close(fig);
end
function show_grid(im,titleCell,nr,nc)
    for ii=1:numel(im)
        subplot(nr,nc,ii);imshow(im{ii},[]);title(titleCell{ii});
    end
end

function y=mirror_mean_3x3(x)
    % Reflection about the boundary pixel center WITHOUT repeating that pixel.
    nr=size(x,1);nc=size(x,2);
    rows=[2,1:nr,nr-1];cols=[2,1:nc,nc-1];
    padded=x(rows,cols);
    y=conv2(padded,ones(3,3)/9,'valid');
end
